  ("lorem.paragraphs(2)", 42, {x|["شارۆچکە زۆر ژمارە چیرۆک چیرۆک. هەرگیز ژمارە ئازادی. کوردستان جوان کورد.\nهەرزان شەو دەنگ ئەو. ژمارە دوو شەو کەسی کار. ڕۆژ دەنگ ژمارە ئامادە ژمارە هەرزان ناوچە شارۆچکە کوردستان.","شەو هەواڵ باش ئەو زمان وەکو پێش دەست مەزنی. هەوا دەنگ ماڵ ڕۆژ کوردستان بوون شارۆچکە هەموو. هەمووان هەواڵ ڕۆژ ئامادە هەوا گەرمی خێزان.\nکەسی خێزان ماڵ دوو تکایە ناوچە پەیام بوون ڕۆژ. تکایە ئازادی زۆر. ناوچە کەسی زمان هەرگیز کۆمەڵ شار ناوچە هەوا هەوا."]|x});
  ("lorem.paragraphs(2)", 1337, {x|["چیرۆک خێزان کار هەوا دەنگ. کوردستان زۆر زمان دەریا کۆمەڵ. پەیام ئەو نووسین نووسین.\nبەفر هەست بوون ڕۆژ شەو. وەکو هەرزان بەفر ڕۆژ ماڵ جوان ڕۆژ شارۆچکە. وەکو دەنگ سڵاو زۆر پەیام چیرۆک.","دەریا باش سڵاو دەریا. نووسین کەسی ئازادی. کوردستان جوان ژمارە گۆڕانکاری پەیام مەزنی.\nهەواڵ شارۆچکە کوردستان. شار زۆر سڵاو بوون سەرکەوتن ڕۆژ. دەست چیرۆک دەست هەوا ئازادی خێزان دەنگ هەرزان."]|x});
  ("lorem.paragraphs(2)", 7, {x|["نووسین ئەو زۆر. ماڵ وەکو ناوچە خێزان وەکو باش تکایە دەریا ناوچە شەو. کورد کار هەمووان پێش ژمارە شارۆچکە ناو ماڵ دەست دوو.\nمەریوان سەرکەوتن کار کورد وەکو دەریا تایبەت. ڕەنگ بوون هەوا هەست خێزان. کەسی سەرکەوتن دەریا کار زۆر بەفر.","هەرزان مەریوان بەفر بەفر پێویست دەنگ بەفر سڵاو هەواڵ ئازادی. ئازادی شارۆچکە باش ئامادە هەوا ژمارە ناو. شارۆچکە ڕەنگ تایبەت ڕەنگ دوو هەوا کار مەریوان تایبەت دوو.\nهەوا شەو هەرزان بەفر ئەو. تکایە دەنگ کار نووسین هەموو باش تکایە شارۆچکە پێش. خێزان تایبەت تکایە زۆر چیرۆک سەرکەوتن ناوچە کەسی تکایە بەفر."]|x});
